// Normalize the job row handed over by the intake workflow.
const input = $input.first().json;
const job = Array.isArray(input) ? input[0] : input;
const job_id = job.id || job.job_id;
if (!job_id) throw new Error('No job_id received from intake workflow');
return { job_id, job };

const input = $input.first().json;
const content = input && input.choices && input.choices[0]
  ? (input.choices[0].message && input.choices[0].message.content) || input.choices[0].text
  : null;
if (!content) throw new Error('DeepSeek returned no content: ' + JSON.stringify(input).slice(0, 500));
let cleaned = String(content).trim();
const fenced = cleaned.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
if (fenced) cleaned = fenced[1].trim();
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error('DeepSeek score response is not JSON: ' + cleaned.slice(0, 500));
}
const score_total = Number(parsed.score_total);
const confidence = Number(parsed.confidence);
if (!Number.isFinite(score_total) || score_total < 0 || score_total > 10) throw new Error('Invalid score_total: ' + score_total);
if (!Number.isFinite(confidence) || confidence < 0 || confidence > 1) throw new Error('Invalid confidence: ' + confidence);
if (!['APPLY', 'REVIEW', 'SKIP'].includes(parsed.recommendation)) throw new Error('Invalid recommendation: ' + parsed.recommendation);
return {
  score_total,
  confidence,
  recommendation: parsed.recommendation,
  explanation: String(parsed.explanation || ''),
  factors: parsed.factors || {}
};
